\begin{proposition}\label{pro:cascade-net}
	Consider two multiport networks connected in cascade as illustrated in Fig. \ref{Fig:cascade}. Let the first network be an $N_a$-port network, where $N_a=n_a+n_c$, with scattering matrix
	\begin{equation}
		\mathbf{S}^a=
		\begin{bmatrix}
 \mathbf{S}^a_{11} & \mathbf{S}^a_{12}
 \mathbf{S}^a_{21} & \mathbf{S}^a_{22}
		\end{bmatrix},
	\end{equation}
	where $\mathbf{S}^a_{11}\in\mathbb{C}^{n_a\times n_a}$ and $\mathbf{S}^a_{22}\in\mathbb{C}^{n_c\times n_c}$. Let the second network be an $N_b$-port network, where $N_b=n_c+n_b$, with scattering matrix
	\begin{equation}
		\mathbf{S}^b=
		\begin{bmatrix}
 \mathbf{S}^b_{11} & \mathbf{S}^b_{12}
 \mathbf{S}^b_{21} & \mathbf{S}^b_{22}
		\end{bmatrix},
	\end{equation}
		where $\mathbf{S}^b_{11}\in\mathbb{C}^{n_c\times n_c}$ and $\mathbf{S}^b_{22}\in\mathbb{C}^{n_b\times n_b}$. Suppose that the last $n_c$ ports of the first network are connected one-to-one to the first $n_c$ ports of the second network. Assuming that the matrix inverses appearing below exist, the resulting interconnected network is an $N_c$-port network, where $N_c=n_a+n_b$, with scattering matrix
	\begin{equation}
		\mathbf{S}^c=
		\begin{bmatrix}
 \mathbf{S}^c_{11} & \mathbf{S}^c_{12}
 \mathbf{S}^c_{21} & \mathbf{S}^c_{22}
		\end{bmatrix},
	\end{equation}
	whose submatrices are given by
	\begin{subequations}
		\begin{align}
 \mathbf{S}^c_{11}
 =&
 \mathbf{S}^a_{11}
 +
 \mathbf{S}^a_{12}
 \left(\mathbf{I}-\mathbf{S}^b_{11}\mathbf{S}^a_{22}\right)^{-1}
 \mathbf{S}^b_{11}\mathbf{S}^a_{21},
 \mathbf{S}^c_{12}
 =&
 \mathbf{S}^a_{12}
 \left(\mathbf{I}-\mathbf{S}^b_{11}\mathbf{S}^a_{22}\right)^{-1}
 \mathbf{S}^b_{12},
 \mathbf{S}^c_{21}
 =&
 \mathbf{S}^b_{21}
 \left(\mathbf{I}-\mathbf{S}^a_{22}\mathbf{S}^b_{11}\right)^{-1}
 \mathbf{S}^a_{21},
 \mathbf{S}^c_{22}
 =&
 \mathbf{S}^b_{22}
 +
 \mathbf{S}^b_{21}
 \left(\mathbf{I}-\mathbf{S}^a_{22}\mathbf{S}^b_{11}\right)^{-1}
 \mathbf{S}^a_{22}\mathbf{S}^b_{12}.
		\end{align}
	\end{subequations}
\end{proposition}
\textit{Proof:}  
The detailed proof follows the procedure in \cite[Appendix]{matteo-SIM}.
\hfill$\square$
Applying Proposition~\ref{pro:cascade-net} to the cascade of MiLAC~1 and $D$ amplifiers, we obtain the scattering matrix 
\begin{equation}
	\bm{\Omega}_1 =
	\begin{bmatrix}
		\bm{\Omega}_{1,11} & \bm{\Omega}_{1,12}
		\bm{\Omega}_{1,21} & \bm{\Omega}_{1,22}
	\end{bmatrix},
\end{equation}
with
\begin{subequations}
	\begin{align}
		\bm{\Omega}_{1,11}
		=&
		\bm\Theta_{1,11}
		+
		\bm\Theta_{1,21}^\mathsf{T}
		\left(\mathbf{I}-\mathbf{S}_{A,11}\bm\Theta_{1,22}\right)^{-1}
		\mathbf{S}_{A,11}\bm\Theta_{1,21},
		\bm{\Omega}_{1,12}
		=&
		\bm\Theta_{1,21}^\mathsf{T}
		\left(\mathbf{I}-\mathbf{S}_{A,11}\bm\Theta_{1,22}\right)^{-1}
		\mathbf{S}_{A,12},

		\bm{\Omega}_{1,21}
		=&
		\mathbf{S}_{A,21}
		\left(\mathbf{I}-\bm\Theta_{1,22}\mathbf{S}_{A,11}\right)^{-1}
		\bm\Theta_{1,21},

		\bm{\Omega}_{1,22}
		=&
		\mathbf{S}_{A,22}
		+
		\mathbf{S}_{A,21}
		\left(\mathbf{I}-\bm\Theta_{1,22}\mathbf{S}_{A,11}\right)^{-1}
		\bm\Theta_{1,22}\mathbf{S}_{A,12}.
	\end{align}
\end{subequations}
Cascading the resulting network with MiLAC~2 and
applying Proposition~\ref{pro:cascade-net} again yields
\begin{equation}
	\bm{\Omega}_2 =
	\begin{bmatrix}
		\bm{\Omega}_{2,11} & \bm{\Omega}_{2,12}
		\bm{\Omega}_{2,21} & \bm{\Omega}_{2,22}
	\end{bmatrix},
\end{equation}
with
\begin{subequations}
	\begin{align}
		\bm{\Omega}_{2,11}
		=&
		\bm{\Omega}_{1,11}
		+
		\bm{\Omega}_{1,12}
		\left(\mathbf{I}-\bm \Theta_{2,11}\bm{\Omega}_{1,22}\right)^{-1}
		\bm \Theta_{2,11}\bm{\Omega}_{1,21},

		\bm{\Omega}_{2,12}
		=&
		\bm{\Omega}_{1,12}
		\left(\mathbf{I}-\bm \Theta_{2,11}\bm{\Omega}_{1,22}\right)^{-1}
		\bm\Theta_{2,21}^\mathsf{T},

		\bm{\Omega}_{2,21}
		=&
		\bm \Theta_{2,21}
		\left(\mathbf{I}-\bm{\Omega}_{1,22}\bm \Theta_{2,11}\right)^{-1}
		\bm{\Omega}_{1,21},

		\bm{\Omega}_{2,22}
		=&
		\bm \Theta_{2,22}
		+
		\bm \Theta_{2,21}
		\left(\mathbf{I}-\bm{\Omega}_{1,22}\bm \Theta_{2,11}\right)^{-1}
		\bm{\Omega}_{1,22}\bm\Theta_{2,21}^\mathsf{T}.
	\end{align}		
\end{subequations}
Hence, the complete two-layer architecture can be represented as a single composite multiport network in Fig. \ref{Fig:sys-model-S}. The inner dashed boundary encloses MiLAC 1 and the amplifier bank, with composite scattering matrix $\bm{\Omega}_1$. The outer solid boundary encloses the complete two-layer network, with scattering matrix $\bm{\Omega}_2$. The corresponding end-to-end relationship between the input $\mathbf{s}$ and output $\mathbf{x}$ is given by \eqref{eq:beamforming-whole}.
