\stepcounter{equation}
To obtain a tractable representation of the proposed two-layer MiLAC architecture, we adopt the following two assumptions on the intermediate amplifiers.
\begin{assumption}[Unilateral amplifiers]\label{assu:uni}
	Each amplifier is assumed to be unilateral, i.e., there is no reverse transmission from its output port to its input port.
\end{assumption}
Under Assumption \ref{assu:uni}, we have $S_{d,12}=0, \forall d\in\mathcal{D}$ or, equivalently, $\mathbf{S}_{A, 12}=\mathbf{0}_{D\times D}$. Accordingly, \eqref{eq:beamforming-whole} simplifies to
\begin{equation}\label{eq:re-assum1}
		\mathbf{x}
		=\frac{1}{2}
		\bm \Theta_{2,21} \bm \Lambda
		\bm\Theta_{1,21} \mathbf{s},
\end{equation}
where $\bm \Lambda =\left(\mathbf{I}-\mathbf{S}_{A,22}\bm\Theta_{2,11}\right)^{-1}
\mathbf{S}_{A,21}
\left(\mathbf{I}-\bm\Theta_{1,22}\mathbf{S}_{A,11}\right)^{-1}$.	
The unilateral assumption provides a useful approximation for many transistor devices~\cite[Sec.~12.1]{pozar2021microwave}.
\begin{assumption}[Perfectly matched amplifiers]\label{assu:perf}
	The input and output ports of each amplifier are assumed to be perfectly matched to the reference impedance $Z_0$.
\end{assumption}
 Under both Assumption \ref{assu:uni} and \ref{assu:perf}, we have the corresponding input and output reflection coefficients of each amplifier vanish, i.e., $ S_{d,11}=S_{d,22}=0, \forall d\in\mathcal{D}$, which gives $ \mathbf{S}_{A, 11} = \mathbf{S}_{A, 22} = \mathbf{0}_{D\times D}$. Therefore, the scattering matrix $\mathbf{S}_A$ for the $D$ amplifiers becomes
\begin{equation}
	\mathbf{S}_A=\begin{bmatrix}
		\mathbf{0}&\mathbf{0}
		\mathbf{S}_{A,21}&\mathbf{0}
	\end{bmatrix}.
\end{equation}
Substituting these assumptions into the input–output relationship of the transmitter in \eqref{eq:beamforming-whole} yields
	\begin{equation}\label{eq:simplified}
	\begin{split}
		\mathbf{x}= \frac{1}{2}
		\bm \Theta_{2,21}
		\mathbf{S}_{A,21}
		\bm\Theta_{1,21} \mathbf{s}.
	\end{split}
\end{equation}	
In the remainder of this paper, we adopt the simplified
model in \eqref{eq:simplified} for transceiver analysis and design.
\begin{remark}
 Figs. \ref{Fig:sys-model-S} and \ref{Fig:sys-transceiver} show an equivalent representation of the proposed architecture and do not prescribe the physical placement of conventional power amplifiers (PAs). In the simplified model in \eqref{eq:simplified}, the intermediate stage implements the nonuniform amplitude weights required to distribute power among the input ports of MiLAC~2. The diagonal gain matrix can be factored as $\mathbf{S}_{A,21}=\alpha \mathbf{A}$, where $\alpha>0$ is a common amplitude gain and $\mathbf{A}$ is a diagonal attenuation matrix. Thus, \eqref{eq:simplified} can be equivalently expressed as 
 \begin{equation*}
 	\begin{split}
 \mathbf{x} =& \frac{1}{2}
 \bm \Theta_{2,21}
 \left(\alpha \mathbf{A}\right)
 \bm\Theta_{1,21} \mathbf{s}
 =& \frac{1}{2}
 \left(\alpha \bm \Theta_{2,21}\right) 
 	\mathbf{A}
 \bm\Theta_{1,21} \mathbf{s}
 =& \frac{1}{2}
 \bm \Theta_{2,21}
 \mathbf{A}
 \left(\alpha \bm\Theta_{1,21}\right) \mathbf{s}.
 	\end{split}
 \end{equation*}
 Since the scalar gain $\alpha$ commutes with both MiLAC transmission matrices, conventional PAs providing this common gain may be placed before MiLAC~1, between the two MiLAC layers, or after MiLAC~2 without changing the input-output relationship in \eqref{eq:simplified}. In contrast, $\mathbf{A}$ generally does not commute with the MiLAC transmission matrices and is therefore retained between the two layers to preserve the required nonuniform amplitude weighting. The physical placement of the PAs remains subject to hardware constraints, including power handling, impedance matching, and PA linearity.
\end{remark}

	\section{MiLAC-Aided Multi-User MIMO System Model}\label{Sec:system model}

	Building on the simplified transmitter input–output relationship in \eqref{eq:simplified}, we now develop a system-level model for a narrowband downlink multi-user MIMO system employing the proposed MiLAC architecture. As illustrated in Fig.~\ref{Fig:sys-transceiver}, the base station employs a two-layer MiLAC transmitter, while each user employs a single-layer MiLAC receiver. This asymmetric configuration follows from the different requirements of transmit precoding and receive combining: a single-layer MiLAC can realize an arbitrary receive combiner up to a scaling factor that does not affect the achievable rate, whereas two MiLAC layers are generally required to realize an arbitrary fully digital precoder without a transmit-power loss.


	The transmitter is equipped with $L$ antennas and simultaneously serves $K$ users by transmitting $D$ data streams in parallel, while user $k$ is equipped with $N_k$ receive antennas and requires $D_k$ independent data streams. Here, we assume $D \leq \min \{L, \sum_{k =1}^K N_k\}$ and $D_k \leq \min \{L, N_k\}$. Let $\mathbf{s}_k \in \mathbb{C}^{D_k \times 1}$ denote the data symbol vector intended for user $k$, where $
	\mathbf{s}_k \sim \mathcal{CN}\left(\mathbf{0},\mathbf{I}_{D_k}\right)$. The aggregate data symbol vector for all users is given by 
	$\mathbf{s}
	=
	\begin{bmatrix}
		\mathbf{s}_1^{T},
		\mathbf{s}_2^{T},
		\ldots,
		\mathbf{s}_K^{T}
	\end{bmatrix}^{T}
	\in \mathbb{C}^{D \times 1}$,
	where $D=\sum_{k=1}^{K}D_k$ denotes the total number of transmitted data streams. Assuming that the data streams are mutually independent, we have $
	\mathbf{s}\sim\mathcal{CN}\left(\mathbf{0},\mathbf{I}_D\right)$.
	At the transmitter, beamforming is implemented using the proposed two-layer MiLAC-aided architecture with $M_1=2D$, $M_2=L+D$. First, the $D$ data streams intended for the users are processed in parallel by $D$ RF chains, which convert the digital symbols into analog RF signals before they are fed into MiLAC~1. As discussed earlier, the MiLAC architecture allows the RF chains to directly process the original constellation symbols, thereby enabling the use of low-resolution DACs. The outputs of the RF chains are then fed into the input ports of MiLAC~1, which performs the first-stage analog precoding. Subsequently, the $D$ output signals of MiLAC~1 are passed through $D$ parallel amplifiers located between MiLAC~1 and MiLAC~2, which implement power allocation. Finally, MiLAC~2 performs the second-stage analog precoding, thereby mapping the $D$ input signals to the $L$ transmit antennas.

\subsection{Transmitter Model}
With the proposed two-layer MiLAC architecture, the output signal of MiLAC 1 is given by
 	\begin{equation}
 \bm{\tau} = \mathbf{F}\mathbf{s},
 	\end{equation}
 	where $\mathbf{F} \in \mathbb{C}^{D \times D}$ denotes the first-stage analog beamforming matrix. Based on the relationship between the scattering matrix and the MiLAC-aided beamforming matrix~\cite{nerini2025milac-capacity,nerini2025mimo,limits-milac}, we have
 	\begin{equation}\label{eq:theta1}
 \mathbf{F}
 =
 \bm{\Theta}_{1,21}.
 	\end{equation}
 Note that $\mathbf F$ is defined directly in terms of the transmission block of the scattering matrix. The normalization factor associated with the overall MiLAC input-output relation is accounted for in the subsequent definition of the amplifier power-allocation coefficients.


 	Let $\mathbf{P}
 	=
 	\operatorname{diag}(p_1,p_2,\ldots,p_D)
 	\in \mathbb{R}^{D \times D}$
 	denote the power allocation matrix associated with the $D$ amplifiers between MiLAC 1 and MiLAC 2, where $p_d \geq 0$ represents the power allocated to the $d$-th intermediate signal stream. After amplitude adjustment and power allocation, the input signal to MiLAC 2 is given by
 	\begin{equation}
 \mathbf{c}
 =
 \frac{1}{2}\mathbf{P}^{\frac{1}{2}}\bm{\tau}
 =
 \frac{1}{2}\mathbf{P}^{\frac{1}{2}}\mathbf{F}\mathbf{s},
 	\end{equation}
 	where $	\mathbf{P}^{\frac{1}{2}}
 	=
 	\operatorname{diag}\left(
 	\sqrt{p_1},\sqrt{p_2},\ldots,\sqrt{p_D}
 	\right)
 	\in \mathbb{R}^{D \times D}$ 
 	is the principal square root of the power allocation matrix and $p_d=|S_{d,21}|^2\geq0$\footnote{We assume that the power amplifiers do not introduce any phase shift to the signal, i.e., $\arg(S_{d,21})=0$. Even if phase shifts are introduced, we assume that they are known and can be compensated by reconfiguring one of the two MiLACs accordingly.} denotes the power-allocation coefficient associated with the $d$-th amplifier. The power allocation coefficients satisfy $\sum_{d=1}^{D} p_d \leq P_t$, where $P_t$ denotes the transmit power budget. Finally, after second-stage analog beamforming by MiLAC 2, the transmit signal vector at the transmitter is
 	\begin{equation}\label{eq:x-s-beamforming}
 \mathbf{x}
 =
 \mathbf{W}\mathbf{c}
 =
 \frac{1}{2}\mathbf{W}\mathbf{P}^{\frac{1}{2}}\mathbf{F}\mathbf{s},
 	\end{equation}
 	where $\mathbf{W} \in \mathbb{C}^{L \times D}$ denotes the second-stage analog beamforming matrix. Similarly to \eqref{eq:theta1}, the analog beamforming matrix $\mathbf{W}$ implemented by MiLAC~2 is given by
 	\begin{equation}\label{eq:theta2}
 \mathbf{W}
 =
 \bm{\Theta}_{2,21}.
 	\end{equation}

Comparing \eqref{eq:simplified} and \eqref{eq:x-s-beamforming}, the forward scattering matrix of the $D$ amplifiers is related to the power-allocation matrix as
\begin{equation}\label{eq:amplifier-gain}
 \mathbf{P}^{\frac{1}{2}}=\mathbf{S}_{A,21}.
\end{equation}
\subsection{Receiver Model}
 The signal $\mathbf{y}_k \in \mathbb{C}^{N_k \times 1}$ received at user $k$ is given by
	\begin{equation}
		\begin{split}
 \mathbf{y}_k
 =&\mathbf{H}_k\mathbf{x}+\mathbf{n}_k
 =&\frac{1}{2}\mathbf{H}_k\mathbf{W}\mathbf{P}^{\frac{1}{2}} \mathbf{F}\mathbf{s}+\mathbf{n}_k
 =&\frac{1}{2}\mathbf{H}_k\mathbf{W}\mathbf{P}^{\frac{1}{2}} \mathbf{F}_k\mathbf{s}_k +\frac{1}{2} \sum_{i \neq k}\mathbf{H}_k\mathbf{W}\mathbf{P}^{\frac{1}{2}} \mathbf{F}_i\mathbf{s}_i+\mathbf{n}_k,
		\end{split}
	\end{equation}
	where $\mathbf{H}_k\in\mathbb{C}^{N_k\times L}$ denotes the channel matrix from the transmitter to user~$k$ and $\mathbf{n}_k\sim\mathcal{CN}
(\mathbf{0},\sigma_k^2\mathbf{I}_{N_k})$ denotes the additive noise. Moreover, $\mathbf{F}_k\in\mathbb{C}^{D\times D_k}$ is the submatrix of $\mathbf{F}$ associated with user~$k$, such that $\mathbf{F}=[\mathbf{F}_1,\ldots,\mathbf{F}_K]$.
	At each user, linear receive combining is implemented using a single-layer MiLAC. Specifically, user~$k$ employs an $(N_k+D_k)$-port MiLAC. Let $T_k= N_k+D_k$, and denote the scattering matrices of the receiver-side MiLAC by
$\bm{\Psi}_k\in\mathbb{C}^{T_k\times T_k}$.
Following the models of MiLAC~1 and MiLAC~2, the analog combining matrix $\mathbf{U}_k\in\mathbb{C}^{N_k\times D_k}$ is given by
		\begin{equation}\label{eq:psi}
 \mathbf{U}_k
 =
 \frac{1}{2}
 [\bm{\Psi}_k]_{D_k+1:T_k,\,1:D_k},
 \qquad
 \forall k\in \mathcal{K},
\end{equation}
where $\mathcal{K} = \{1,\ldots,K\}$ is the user index set.

 Treating multi-user interference as noise, the estimate of the data symbol vector $\mathbf{s}_k$ is
\begin{equation}\label{eq:receive-signal}
 \hat{\mathbf{s}}_k
 =
 \mathbf{U}_k^{\mathsf T}\mathbf{y}_k. \footnote{The receive-side MiLAC is assumed to be lossless and therefore introduces no additional thermal noise. In practice, dissipative components in a lossy MiLAC may introduce insertion loss and additional thermal noise, which are not considered in the present model.}
\end{equation}
Define the effective transmit beamformer for user~$k$ as $\mathbf{G}_k
 =
 \mathbf{W}\mathbf{P}^{\frac{1}{2}}\mathbf{F}_k
 \in\mathbb{C}^{L\times D_k}$. Then, the achievable rate of user~$k$ is
\begin{equation}
 R_k
 =
 \log_2\det\left(
 \mathbf{I}_{D_k}
 +
 \mathbf{U}_k^{\mathsf T}
 \mathbf{H}_k
 \mathbf{G}_k\mathbf{G}_k^{\mathsf H}
 \mathbf{H}_k^{\mathsf H}
 \mathbf{U}_k^*
 \mathbf{J}_k^{-1}
 \right),
\end{equation}
where $\mathbf{J}_k
 =
 \sum_{i\neq k}
 \mathbf{U}_k^{\mathsf T}
 \mathbf{H}_k
 \mathbf{G}_i\mathbf{G}_i^{\mathsf H}
 \mathbf{H}_k^{\mathsf H}
 \mathbf{U}_k^*
 +
 4\sigma_k^2
 \mathbf{U}_k^{\mathsf T}\mathbf{U}_k^*$ denotes the interference-plus-noise covariance matrix that accounts for multi-user interference and noise contribution in the MIMO system.



	Since all MiLACs are assumed to be lossless and reciprocal, their
scattering matrices are unitary and symmetric, and therefore satisfy
\begin{subequations}\label{eq:scattering-constraints}
 \begin{align}
 \bm{\Theta}_m^{\mathsf H}\bm{\Theta}_m
 &=
 \mathbf{I}_{M_m},
 &
 \bm{\Theta}_m
 &=
 \bm{\Theta}_m^{\mathsf T},
 \quad
 \forall m\in\{1,2\},
 \label{eq:con-theta-m}
 \bm{\Psi}_k^{\mathsf H}\bm{\Psi}_k
 &=
 \mathbf{I}_{T_k},
 &
 \bm{\Psi}_k
 &=
 \bm{\Psi}_k^{\mathsf T},
 \quad
 \forall k\in\mathcal{K}.
 \label{eq:cons-psi}
 \end{align}
\end{subequations}
