\section{Proof of Lemma \ref{lemma_-1}}\label{appendix_-1}
Define the random variable $ X = \sum_{n=0}^{M-1} e^{j\delta_n} = X_R+jX_I$, where the real and imaginary components are the random variables $X_R=\sum_{n=0}^{M-1}\cos(\delta_n)$ and $X_I=\sum_{n=0}^{M-1}\sin(\delta_n)$, respectively.
Then, $\nu = \frac{|X|^2}{M^2} = \frac{X_R^2+X_I^2}{M^2}$. Since $\delta_n\sim\mathrm{i.i.d.}\ \mathrm{Unif}[0,2\pi)$, we have $\mathbb E[\cos(\delta_n)]
 =
 \mathbb E[\sin(\delta_n)]
 =
 0$, $\mathrm{Var}(\cos(\delta_n))
 =
 \mathrm{Var}(\sin(\delta_n))
 =
 \frac{1}{2}$, and $\mathbb E[\cos(\delta_n)\sin(\delta_n)]
 =
 0$. Therefore, by the Berry-Esseen theorem \cite{vershynin2026friendly},
\begin{align}
 \left(
 \frac{X_R}{\sqrt{M/2}},
 \frac{X_I}{\sqrt{M/2}}
 \right)
 \xrightarrow{d}
 (Z_1,Z_2),
\end{align}
with an approximation error of order $\mathcal O(1/\sqrt{M})$, where $Z_1$ and $Z_2$ are independent standard normal random variables.
It follows that
\begin{align}
 M\nu
 =
 \frac{1}{2}
 \left[
 \left(\frac{X_R}{\sqrt{M/2}}\right)^2
 +
 \left(\frac{X_I}{\sqrt{M/2}}\right)^2
 \right]
 \xrightarrow{d}
 \frac{1}{2}(Z_1^2+Z_2^2).
\end{align}
Since $Z_1^2+Z_2^2\sim\chi_2^2$, we have $\frac{1}{2}(Z_1^2+Z_2^2) \sim \mathrm{Exp}(1)$. Thus, for large $M$, $M\nu$ is approximately exponentially distributed with unit rate, or equivalently, $\nu$ is approximately exponentially distributed with rate $M$. Hence, $F_\nu(\gamma) = 1-e^{-M\gamma} + \mathcal O\left(\frac{1}{\sqrt{M}}\right)$,
which proves the lemma.
\section{Proof of Lemma \ref{lemma_rp_high_gain}}\label{appendix_rp_highgain}
Let $\epsilon=1-\gamma$. From \eqref{define_gain_RP}, $\nu = \frac{1}{M^2} \left\lvert \sum_{n=0}^{M-1} e^{j\delta_n} \right\rvert^2$, where $\boldsymbol{\delta}=[\delta_0,\ldots,\delta_{M-1}]^{\mathsf T}$
is uniformly distributed over $[0,2\pi)^M$. Expanding the squared
magnitude gives $\nu = 1 - \frac{1}{M^2} \sum_{m,n} 2\sin^2\left(\frac{\delta_m-\delta_n}{2}\right).$
Define the high-gain event $\mathcal D_\epsilon \triangleq \{ \nu \geq 1-\epsilon \}$. Equivalently,
\begin{align}
 \mathcal D_\epsilon
 =
 \left\{
 \sum_{m,n}
 2\sin^2\left(\frac{\delta_m-\delta_n}{2}\right)
 \leq
 M^2\epsilon
 \right\}.
\end{align}
Since all terms in the summation are nonnegative, on
$\mathcal D_\epsilon$ we have $\left| \sin\left(\frac{\delta_m-\delta_n}{2}\right) \right| \leq \frac{M}{\sqrt{2}}\sqrt{\epsilon}, \forall m,n$. Thus, for $M^2\epsilon\ll1$, all phases are close to a common phase
modulo $2\pi$. Equivalently, after unwrapping the phases around this
common phase, $|\delta_m-\delta_n| = \mathcal O(\sqrt{\epsilon}), \forall m,n.$ For any fixed $\rho\in(0,1/2)$ and sufficiently small phase differences,
\begin{align}
 \left(\frac{1}{2}-\rho\right)x^2
 \leq
 2\sin^2\left(\frac{x}{2}\right)
 \leq
 \left(\frac{1}{2}+\rho\right)x^2 .
\end{align}
Therefore, the event $\mathcal D_\epsilon$ is sandwiched as
\begin{align}
 &
 \left\{
 \left(\frac{1}{2}+\rho\right)
 \sum_{m,n}(\delta_m-\delta_n)^2
 \leq
 M^2\epsilon
 \right\}
 \subseteq
 \mathcal D_\epsilon
 \nonumber
 &\hspace{1.4cm}
 \subseteq
 \left\{
 \left(\frac{1}{2}-\rho\right)
 \sum_{m,n}(\delta_m-\delta_n)^2
 \leq
 M^2\epsilon
 \right\}.
\end{align}
Now define $\bar{\delta}
 =
 \frac{1}{M}
 \sum_{n=0}^{M-1}\delta_n$ and $\widetilde{\boldsymbol{\delta}}
 =
 \boldsymbol{\delta}
 -
 \bar{\delta}\mathbf 1.$
Using the identity
\begin{align}
 \sum_{m,n}
 (\delta_m-\delta_n)^2
 =
 2M
 \sum_{n=0}^{M-1}
 (\delta_n-\bar{\delta})^2
 =
 2M
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2,
\end{align}
the sandwich becomes
\begin{align}
 \left\{
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2
 \leq
 \frac{M\epsilon}{1+2\rho}
 \right\}
 \subseteq
 \mathcal D_\epsilon
 \subseteq
 \left\{
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|^2
 \leq
 \frac{M\epsilon}{1-2\rho}
 \right\}.
\end{align}
The centered vector $\widetilde{\boldsymbol{\delta}}$ lies in the
$(M-1)$-dimensional hyperplane $\mathcal H
 =
 \left\{
 \mathbf x\in\mathbb R^M:
 \mathbf 1^{\mathsf T}\mathbf x=0
 \right\}.$ The remaining degree of freedom is the common phase. Since the gain is
invariant to a common phase rotation, this degree of freedom contributes
a factor equal to the length of the diagonal circle, namely
$2\pi\sqrt{M}$. Hence, for a ball of radius $R$ in $\mathcal H$,
\begin{align}
 \Pr\left\{
 \left\|
 \widetilde{\boldsymbol{\delta}}
 \right\|
 \leq R
 \right\}
 =
 \frac{2\pi\sqrt{M}}{(2\pi)^M}
 V_{M-1}(R),
\end{align}
where $V_{M-1}(R)$ is the volume of an $(M-1)$-dimensional Euclidean ball
of radius $R$. Since $V_{M-1}(R) = \frac{\pi^{\frac{M-1}{2}}}{\Gamma\left(\frac{M+1}{2}\right)} R^{M-1}$,we obtain
\begin{align}
 &
 C_M
 (1+2\rho)^{-\frac{M-1}{2}}
 \epsilon^{\frac{M-1}{2}}
 \leq
 \Pr\{\mathcal D_\epsilon\}
 \nonumber
 &\hspace{2cm}
 \leq
 C_M
 (1-2\rho)^{-\frac{M-1}{2}}
 \epsilon^{\frac{M-1}{2}},
\end{align}
where $C_M = \frac{M^{\frac{M}{2}}}{2^{M-1}\pi^{\frac{M-1}{2}}\Gamma\left(\frac{M+1}{2}\right)}$, and $\Gamma(\cdot)$ is the Gamma function.
Since $\rho>0$ is arbitrary, letting $\rho\to0$ gives $\Pr\{\mathcal D_\epsilon\}
 \sim
 C_M
 \epsilon^{\frac{M-1}{2}}.$ Using the small-angle expansion $2\sin^2\left(\frac{x}{2}\right)
 =
 \frac{x^2}{2}
 +
 \mathcal O(x^4)$, and the fact that $x=\mathcal O(\sqrt{\epsilon})$ in the high-gain
region, the radius of the high-gain region can be written as $r_\epsilon
 =
 \sqrt{M\epsilon}
 \left(1+\mathcal O(\epsilon)\right).$ Therefore,
\begin{align}
 \Pr\{\nu\geq 1-\epsilon\}
 =
 C_M
 \epsilon^{\frac{M-1}{2}}
 +
 \mathcal O\left(
 \epsilon^{\frac{M+1}{2}}
 \right).
\end{align}
Substituting $\epsilon=1-\gamma$ yields
\begin{align}
 F_\nu(\gamma)
 =
 1
 -
 C_M
 (1-\gamma)^{\frac{M-1}{2}}
 +
 \mathcal O\left(
 (1-\gamma)^{\frac{M+1}{2}}
 \right),
\end{align}
which proves the lemma.
\section{Proof of Lemma \ref{lemma_0}}\label{appendix_0}
After changing variables in \eqref{lemma_eqn} using \(\ell=n-m\), the beamforming gain can be written as
\begin{align}
 \nu_k =
 \frac{1}{M^2}
 \sum_{\ell=-M+1}^{M-1}
 \sum_{m=\max\{0,-\ell\}}^{\min\{M-1,M-1-\ell\}}
 e^{j\pi\left(A(2m\ell+\ell^2)+(\theta_k-\theta_t)\ell\right)}.
\end{align}
We separate the summation into the three cases \(\ell<0\), \(\ell=0\), and \(\ell>0\). For \(\ell=0\), the exponential term is equal to \(1\), and hence the inner sum contributes $\sum_{m=0}^{M-1} 1 = M$.
Therefore, $\nu_k = \frac{\zeta_1 + M + \zeta_2}{M^2}$, where
\begin{align}
 \zeta_1
 &\triangleq
 \sum_{\ell=-M+1}^{-1}
 \sum_{m=-\ell}^{M-1}
 e^{j\pi\left(A(2m\ell+\ell^2)+\ell(\theta_k-\theta_t)\right)},
 \zeta_2
 &\triangleq
 \sum_{\ell=1}^{M-1}
 \sum_{m=0}^{M-1-\ell}
 e^{j\pi\left(A(2m\ell+\ell^2)+\ell(\theta_k-\theta_t)\right)}.
\end{align}
We first simplify \(\zeta_1\). Letting \(\ell \mapsto -\ell\), we obtain
\begin{align}
 \zeta_1
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi\left(A\ell^2-\ell(\theta_k-\theta_t)\right)}
 \sum_{m=\ell}^{M-1} e^{-j2\pi A\ell m}.
\end{align}
The inner sum is geometric, and applying the finite geometric-series identity yields
\begin{align}
 \sum_{m=\ell}^{M-1} e^{-j2\pi A\ell m}
 =
 e^{-j\pi A\ell(M+\ell-1)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Substituting this into the expression for \(\zeta_1\) gives
\begin{align}\label{delta_1_simplify_rewrite}
 \zeta_1
 =
 \sum_{\ell=1}^{M-1}
 e^{-j\pi \ell\big(A(M-1)+\theta_k-\theta_t\big)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Similarly, for \(\zeta_2\),
\begin{align}
 \zeta_2
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi\left(A\ell^2+\ell(\theta_k-\theta_t)\right)}
 \sum_{m=0}^{M-1-\ell} e^{j2\pi A\ell m}.
\end{align}
Again using the geometric-series identity, the inner sum becomes
\begin{align}
 \sum_{m=0}^{M-1-\ell} e^{j2\pi A\ell m}
 =
 e^{j\pi A\ell(M-1-\ell)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Hence,
\begin{align}\label{delta_2_simplify_rewrite}
 \zeta_2
 =
 \sum_{\ell=1}^{M-1}
 e^{j\pi \ell\big(A(M-1)+\theta_k-\theta_t\big)}
 \frac{\sin\big(\pi(M-\ell)A\ell\big)}{\sin(\pi A\ell)}.
\end{align}
Finally, substituting \eqref{delta_1_simplify_rewrite} and \eqref{delta_2_simplify_rewrite} into $\nu_k = \frac{\zeta_1+M+\zeta_2}{M^2}$, and using $e^{j\theta} + e^{-j\theta} = 2\cos(\theta)$, we obtain \eqref{nu_A_B}, which proves the lemma.
\section{Proof of Lemma \ref{lemma_1} }\label{appendix_A}
Define $u(p) \triangleq \frac{p}{\sin(\pi Ap)}$. Then, from \eqref{define_f}, $f_p(\theta_t, r_t) = u(p)\sin(\pi(M-p)Ap)$. We first approximate \(u(p)\). From \eqref{define_A_range} $A(\theta_t,r_t) \in \left[0, A_{\max} \right]$. This bound shows that the maximum possible value of $A(\theta_t,r_t)$ decreases as $M$ increases. Therefore, over the entire considered user region, $A(\theta_t,r_t)$ is small for large $M$, which justifies the use of small-angle expansion.
Using $\sin x = x + \mathcal{O}(x^3)$, with \(x=\pi Ap\), we obtain $\sin(\pi Ap) = \pi Ap\left(1+\mathcal{O}\left(A^2p^2\right)\right)$. Substituting this into \(u(p)\) gives $u(p) = \frac{1}{\pi A \left(1+\mathcal{O}\left(A^2p^2\right)\right)}$. Since $p\in [1,M-1]$ and $A \in \left[0, A_{\max} \right]$, we have $A^2p^2 \leq A_{\max}^2 (M-1)^2 = \mathcal{O}(\frac{1}{M})$. Thus, for all \(p\in\{1,2,\ldots,M-1\}\),
\begin{align}
 u(p)
 = \frac{1}{\pi A}\left(1+\mathcal{O}\left(\frac{1}{M}\right)\right).
\end{align}
Hence, for large \(M\), \(u(p)\) is approximately constant over the entire range of interest. Next, notice that the second factor in $f_p(\theta_t, r_t)$ is exactly symmetric under the reflection \(p \mapsto M-p\).
Specifically, $\sin(\pi(M-(M-p))A(M-p)) = \sin(\pi(M-p)Ap)$. Hence, the term $\sin(\pi(M-p)Ap)$ is exactly symmetric about $p = M/2$. Therefore, for large \(M\), $f_p(\theta_t, r_t)$ is approximately even about \(p=M/2\), which proves the lemma.
\section{Proof of Lemma \ref{lemma_2} }\label{appendix_B}
From Lemma \ref{lemma_1}, the function $f_p(\theta_t, r_t)$ is approximately even about $p= \frac{M}{2}$ for large $M$. Therefore, in \eqref{define_derivative},
the summation approximately cancels if $g_p(\theta_k, \theta_t, r_t)$ is odd about \(p=M/2\). Define $C \triangleq A(M-1)+\theta_k-\theta_t$ so that $ g_p(\theta_k, \theta_t, r_t) =\sin(\pi p C)$. For $ g_p(\theta_k, \theta_t, r_t) $ to be odd about $p=M/2$, we require $g_{M-p}(\theta_k, \theta_t, r_t)=-g_p(\theta_k, \theta_t, r_t)$. If $C=\frac{2b}{M}, b\in\mathbb Z$,
then $\pi MC=2b\pi$, and hence $g_{M-p}(\theta_k, \theta_t, r_t) = \sin\left(2b\pi-\pi pC\right) = -g_p(\theta_k, \theta_t, r_t)$. Thus, $g_p(\theta_k, \theta_t, r_t)$ is odd about $p=M/2$ for $\theta_k^{(b)} = \theta_t-A(M-1)+\frac{2b}{M}, b\in\mathbb Z$.

To quantify the residual, write
$
h(p)\triangleq \sin(\pi A p(M-p)).
$
Since
$
\frac{p}{\sin(\pi Ap)} = \frac{1}{\pi A} + \mathcal O(Ap^2)$, we have $ f_p(\theta_t,r_t) = \frac{h(p)}{\pi A} + h(p)\mathcal O(Ap^2)$. Since the first term is exactly even, only the residual contributes. Since $|h(p)|\leq1$ and $|g_p(\theta_k,\theta_t,r_t)|\leq1$, from \eqref{define_derivative},
$ \left. \frac{\partial \nu_k}{\partial \theta_k} \right|_{\theta_k=\theta_k^{(b)}} = \mathcal O(AM)$.
Since $A\leq A_{\max}=\mathcal O(M^{-3/2})$, the derivative is $\mathcal O(M^{-1/2})$. Hence, $\theta_k^{(b)}$ is an approximate stationary direction for large $M$.
